// Extract return event payload
const body = $input.first().json.body;

if (body.eventType !== 'loan.returned') {
  throw new Error(`Unexpected event type: ${body.eventType}`);
}

return {
  eventId: body.eventId,
  requestId: body.data.requestId,
  loanId: body.data.loanId,
  toolName: body.data.tool ? body.data.tool.name : 'Tool',
  borrowerName: body.data.borrower ? body.data.borrower.displayName : 'Borrower',
  borrowerUserId: body.data.borrower ? body.data.borrower._id : null,
  lenderName: body.data.lender ? body.data.lender.displayName : 'Lender',
  lenderUserId: body.data.lender ? body.data.lender._id : null,
  returnedAt: Date.now()
};

// Format return thank you & confirmation notifications
const item = $input.first().json;

return {
  ...item,
  borrowerSubject: `Tool Return Confirmation: ${item.toolName}`,
  borrowerMessage: `Hi ${item.borrowerName},\n\nThank you for returning ${item.toolName} to ${item.lenderName}! We hope it was helpful for your project.`,
  lenderSubject: `Tool Returned: ${item.toolName}`,
  lenderMessage: `Hi ${item.lenderName},\n\n${item.borrowerName} has returned your ${item.toolName}. Thank you for lending to your neighborhood!`,
  idempotencyKey: `notif:loan_returned:${item.loanId}`,
  summary: `Recorded tool return and sent thank-you notices for loan ${item.loanId} (${item.toolName})`
};
